// Private C2 adapter derived from fixed C1; see source.json and vendor/c1.
import {LIMITS} from './contract.js';
export class AuthoringError extends TypeError{constructor(code,path,message){super(message);this.name='AuthoringError';this.code=code;this.diagnostics=[{code,path,message,action:'Keep accepted source; provide the named supported finite input/binding.',ownerIds:[]}];}}
export const fail=(code,path,message)=>{throw new AuthoringError(code,path,message);};
export function utf8Bytes(s){let n=0;for(let i=0;i<s.length;i++){const c=s.charCodeAt(i);if(c<128)n++;else if(c<2048)n+=2;else if(c>=0xd800&&c<=0xdbff){const low=s.charCodeAt(++i);if(!(low>=0xdc00&&low<=0xdfff))fail('INVALID_UTF8','/','Unpaired surrogate is not valid UTF-8.');n+=4;}else{if(c>=0xdc00&&c<=0xdfff)fail('INVALID_UTF8','/','Unpaired surrogate is not valid UTF-8.');n+=3;}}return n;}
// Exact JSON UTF-8 size without first allocating an oversized serialization.
export function jsonBytes(value,max=6000000){let size=0;const add=n=>{size+=n;if(size>max)fail('AUTHORING_BYTES_LIMIT','/','Serialized data exceeds captured byte bound.');};const string=s=>{add(2);for(let i=0;i<s.length;i++){const c=s.charCodeAt(i);if(c===34||c===92)add(2);else if(c<32)add([8,9,10,12,13].includes(c)?2:6);else if(c<128)add(1);else if(c<2048)add(2);else if(c>=0xd800&&c<=0xdbff){const low=s.charCodeAt(++i);if(!(low>=0xdc00&&low<=0xdfff))fail('INVALID_UTF8','/','Invalid UTF-8 surrogate.');add(4);}else{if(c>=0xdc00&&c<=0xdfff)fail('INVALID_UTF8','/','Invalid UTF-8 surrogate.');add(3);}}};const visit=v=>{if(v===null){add(4);return;}if(typeof v==='string'){string(v);return;}if(typeof v!=='object'){add(JSON.stringify(v).length);return;}add(2);if(Array.isArray(v)){for(let i=0;i<v.length;i++){if(i)add(1);visit(v[i]);}}else{let i=0;for(const [k,x]of Object.entries(v)){if(i++)add(1);string(k);add(1);visit(x);}}};visit(value);return size;}
export class Budget{
 constructor(input={}){this.limits={...LIMITS};for(const [k,v]of Object.entries(input)){if(!Object.hasOwn(LIMITS,k)||!Number.isSafeInteger(v)||v<0||v>LIMITS[k])fail('INVALID_LIMIT','/limits/'+k,'Only explicit nonnegative tightening of known limits is allowed.');this.limits[k]=v;}this.units=0;this.nodes=0;this.inputBytes=0;this.outputBytes=0;this.definitionVisits=0;this.dependencyEdges=0;this.resourceReferences=0;this.maskCellsEvaluated=0;}
 take(n=1){if(!Number.isSafeInteger(n)||n<0||this.units+n>this.limits.plannerUnits)fail('AUTHORING_WORK_LIMIT','/limits/plannerUnits','Command-wide deterministic work exhausted.');this.units+=n;}
 text(s){this.take(Math.ceil(s.length/16));}
 node(depth){this.maxDepthObserved=Math.max(this.maxDepthObserved??0,depth);this.take();if(++this.nodes>this.limits.nodes||depth>this.limits.depth)fail('AUTHORING_NODE_LIMIT','/','Plain-data node/depth budget exhausted.');}
 input(n){if(this.inputBytes+n>this.limits.inputBytes)fail('AUTHORING_INPUT_LIMIT','/','Aggregate command/source/context bytes exceed the bound.');this.inputBytes+=n;}
 output(v){const n=jsonBytes(v,this.limits.outputBytes);this.take(Math.ceil(n/64));if(n>this.limits.outputBytes)fail('AUTHORING_OUTPUT_LIMIT','/','Complete target/plan exceeds output bytes.');this.outputBytes=n;return n;}
 hash(v){this.take(Math.ceil(jsonBytes(v,this.limits.inputBytes)/64));}
 snapshot(){return {unitsCharged:this.units,inputBytes:this.inputBytes,outputBytes:this.outputBytes,definitionVisits:this.definitionVisits,maskCellsEvaluated:this.maskCellsEvaluated,dependencyEdges:this.dependencyEdges,resourceReferences:this.resourceReferences};}
}
